 12→/**
 13→ * CustomThreadPool - simplified thread pool implementation
 14→ *
 15→ * Execution flow (execute method):
 16→ *   1. workerCount < corePoolSize  -> create core Worker to run task
 17→ *   2. workerCount >= corePoolSize -> try to enqueue the task
 18→ *   3. queue full && workerCount < maxPoolSize -> create non-core Worker
 19→ *   4. otherwise -> invoke reject policy
 20→ *
 21→ * Worker: internal class that loops fetching tasks from BlockingQueue
 22→ *   - core threads use take() (block forever)
 23→ *   - non-core threads use poll(timeout) (exit on timeout)
 24→ */
 25→public class CustomThreadPool {
 26→
 27→    // ========== core parameters ==========
 28→    private final int corePoolSize;
 29→    private final int maxPoolSize;
 30→    private final long keepAliveTime;
 31→    private final TimeUnit timeUnit;
 32→    private final BlockingQueue<Runnable> taskQueue;
 33→    private final RejectPolicy rejectPolicy;
 34→
 35→    // ========== runtime state ==========
 36→    private final Set<Worker> workers = new HashSet<>();
 37→    private final ReentrantLock mainLock = new ReentrantLock();
 38→    private final AtomicInteger workerCount = new AtomicInteger(0);
 39→    private volatile boolean isRunning = true;
 40→
 41→    // ========== constructor ==========
 42→    public CustomThreadPool(int corePoolSize, int maxPoolSize, long keepAliveTime,
 43→                            TimeUnit timeUnit, int queueCapacity, RejectPolicy rejectPolicy) {
 44→        if (corePoolSize < 0 || maxPoolSize <= 0 || maxPoolSize < corePoolSize)
 45→            throw new IllegalArgumentException("illegal args");
 46→        this.corePoolSize = corePoolSize;
 47→        this.maxPoolSize = maxPoolSize;
 48→        this.keepAliveTime = keepAliveTime;
 49→        this.timeUnit = timeUnit;
 50→        this.taskQueue = new LinkedBlockingQueue<>(queueCapacity);
 51→        this.rejectPolicy = rejectPolicy;
 52→    }
 53→
 54→    // ========== execute: 3-level scheduling ==========
 55→    public void execute(Runnable task) {
 56→        if (task == null) throw new NullPointerException();
 57→        if (!isRunning) throw new RuntimeException("pool shutdown");
 58→
 59→        int cnt = workerCount.get();
 60→        // Level 1: create core worker
 61→        if (cnt < corePoolSize) {
 62→            if (addWorker(task, true)) return;
 63→            cnt = workerCount.get();
 64→        }
 65→        // Level 2: enqueue
 66→        if (taskQueue.offer(task)) {
 67→            if (!isRunning && taskQueue.remove(task)) rejectPolicy.reject(task, this);
 68→            return;
 69→        }
 70→        // Level 3: create non-core worker
 71→        if (cnt < maxPoolSize) {
 72→            if (addWorker(task, false)) return;
 73→        }
 74→        // Level 4: reject
 75→        rejectPolicy.reject(task, this);
 76→    }
 77→
 78→    // ========== submit: returns Future ==========
 79→    public <T> Future<T> submit(Callable<T> callable) {
 80→        if (callable == null) throw new NullPointerException();
 81→        FutureTask<T> ft = new FutureTask<>(callable);
 82→        execute(ft);
 83→        return ft;
 84→    }
