 91→    public void shutdownNow() {
 92→        isRunning = false;
 93→        mainLock.lock();
 94→        try {
 95→            for (Worker w : workers) w.thread.interrupt();
 96→            taskQueue.clear();
 97→        } finally {
 98→            mainLock.unlock();
 99→        }
100→    }
101→
102→    // ========== addWorker ==========
103→    private boolean addWorker(Runnable firstTask, boolean core) {
104→        for (;;) {
105→            int c = workerCount.get();
106→            if (c >= (core ? corePoolSize : maxPoolSize)) return false;
107→            if (workerCount.compareAndSet(c, c + 1)) break;
108→        }
109→        Worker w = new Worker(firstTask);
110→        mainLock.lock();
111→        try { workers.add(w); } finally { mainLock.unlock(); }
112→        w.thread.start();
113→        return true;
114→    }
115→
116→    private void workerDone(Worker w) {
117→        mainLock.lock();
118→        try { workers.remove(w); workerCount.decrementAndGet(); } finally { mainLock.unlock(); }
119→    }
120→
121→    // ========== monitoring ==========
122→    public int getActiveCount() { return workerCount.get(); }
123→    public int getQueueSize() { return taskQueue.size(); }
124→    public int getPoolSize() { mainLock.lock(); try { return workers.size(); } finally { mainLock.unlock(); } }
125→    public boolean isRunning() { return isRunning; }
126→
127→    // ========== Worker inner class ==========
128→    private class Worker implements Runnable {
129→        final Thread thread;
130→        Runnable firstTask;
131→
132→        Worker(Runnable ft) {
133→            this.firstTask = ft;
134→            this.thread = new Thread(this, "MyPool-worker-" + workerCount.get());
135→        }
136→
137→        public void run() {
138→            Runnable task = firstTask;
139→            firstTask = null;
140→            try {
141→                while (task != null || (task = getTask()) != null) {
142→                    try { task.run(); }
143→                    catch (Exception e) { System.err.println("[" + Thread.currentThread().getName() + "] error: " + e.getMessage()); }
144→                    finally { task = null; }
145→                }
146→            } finally {
147→                System.out.println("[" + Thread.currentThread().getName() + "] exiting");
148→                workerDone(this);
149→            }
150→        }
151→    }
152→
153→    // ========== getTask: all threads use poll(timeout) ==========
154→    private Runnable getTask() {
155→        boolean timedOut = false;
156→        for (;;) {
157→            // If pool shut down and queue empty, exit
158→            if (!isRunning && taskQueue.isEmpty()) return null;
159→            int c = workerCount.get();
160→            // Non-core threads can exit on timeout
161→            boolean timed = c > corePoolSize;
162→            if (timed && timedOut) {
163→                if (workerCount.compareAndSet(c, c - 1)) return null;
164→                continue;
165→            }
166→            try {
167→                // Use poll with timeout for ALL threads so they can detect shutdown
168→                Runnable task = taskQueue.poll(1, TimeUnit.SECONDS);
169→                if (task != null) return task;
170→                // If shutting down, return null to exit
171→                if (!isRunning) return null;
172→                timedOut = true;
173→            } catch (InterruptedException e) {
174→                if (!isRunning) return null;
175→                timedOut = false;
176→            }
177→        }
178→    }
179→
