188→        CustomThreadPool p1 = new CustomThreadPool(2, 4, 60, TimeUnit.SECONDS, 2, new AbortPolicy());
189→        for (int i = 0; i < 10; i++) {
190→            final int id = i;
191→            try {
192→                p1.execute(() -> {
193→                    System.out.println("  [Pool1] Task " + id + " by " + Thread.currentThread().getName());
194→                    try { Thread.sleep(500); } catch (InterruptedException e) {}
195→                });
196→            } catch (RuntimeException e) {
197→                System.out.println("  [REJECTED] Task " + id + ": " + e.getMessage());
198→            }
199→        }
200→        Thread.sleep(2000);
201→        p1.shutdown();
202→        Thread.sleep(1000);
203→
204→        // --- Demo 2: CallerRunsPolicy ---
205→        System.out.println("\n--- Demo 2: CallerRunsPolicy ---");
206→        CustomThreadPool p2 = new CustomThreadPool(2, 4, 60, TimeUnit.SECONDS, 2, new CallerRunsPolicy());
207→        for (int i = 0; i < 10; i++) {
208→            final int id = i;
209→            p2.execute(() -> {
210→                System.out.println("  [Pool2] Task " + id + " by " + Thread.currentThread().getName());
211→                try { Thread.sleep(300); } catch (InterruptedException e) {}
212→            });
213→        }
214→        Thread.sleep(3000);
215→        p2.shutdown();
216→        Thread.sleep(1000);
217→
218→        // --- Demo 3: submit with Future ---
219→        System.out.println("\n--- Demo 3: submit() with Future ---");
220→        CustomThreadPool p3 = new CustomThreadPool(2, 4, 60, TimeUnit.SECONDS, 10, new AbortPolicy());
221→        Future<Integer> f1 = p3.submit(() -> { Thread.sleep(500); return 42; });
222→        Future<String> f2 = p3.submit(() -> { Thread.sleep(300); return "Hello from " + Thread.currentThread().getName(); });
223→        System.out.println("  future1 result: " + f1.get());
224→        System.out.println("  future2 result: " + f2.get());
225→        p3.shutdown();
226→
227→        System.out.println("\n========================================");
228→        System.out.println("  All demos completed!");
229→        System.out.println("========================================");
230→    }
231→}

