/**
 * Java线程池系统复习教程
 * 涵盖ThreadPoolExecutor七大核心参数、工作流程、拒绝策略、阻塞队列等
 * 
 * @author Eruitah
 */
public class ThreadPoolTutorial {

    // ==================== 第一部分：七大核心参数详解 ====================

    /**
     * 1. ThreadPoolExecutor七大核心参数详解
     */
    public static void explainCoreParameters() {
        System.out.println("========================================");
        System.out.println("第一部分：ThreadPoolExecutor七大核心参数详解");
        System.out.println("========================================");

        /*
         * ThreadPoolExecutor构造函数的七个核心参数：
         * 
         * 1. corePoolSize - 核心线程数
         *    - 线程池中保持活动状态的最小线程数
         *    - 即使线程空闲也不会被回收（除非设置allowCoreThreadTimeOut）
         *    - 相当于公司的正式员工，长期雇佣
         * 
         * 2. maximumPoolSize - 最大线程数
         *    - 线程池中允许的最大线程数
         *    - 必须大于等于corePoolSize
         *    - 相当于公司的最大编制人数
         * 
         * 3. keepAliveTime - 线程空闲存活时间
         *    - 当线程数超过corePoolSize时，多余空闲线程的存活时间
         *    - 配合allowCoreThreadTimeOut(true)可以让核心线程也超时
         *    - 相当于临时工的合同期限
         * 
         * 4. unit - keepAliveTime的时间单位
         *    - TimeUnit.SECONDS、TimeUnit.MILLISECONDS等
         * 
         * 5. workQueue - 工作队列（阻塞队列）
         *    - 用于保存等待执行的任务
         *    - 当核心线程都在忙时，新任务先放入队列
         *    - 相当于公司的任务待办清单
         * 
         * 6. threadFactory - 线程工厂
         *    - 用于创建新线程
         *    - 可以自定义线程名、优先级、是否为守护线程等
         *    - 相当于HR部门，负责招聘新员工
         * 
         * 7. handler - 拒绝策略（饱和策略）
         *    - 当线程池和队列都满时，处理新提交任务的策略
         *    - 相当于公司处理超出产能任务的方式
         */

        // 示例：自定义线程工厂
        AtomicInteger threadId = new AtomicInteger(0);
        ThreadFactory customFactory = new ThreadFactory() {
            @Override
            public Thread newThread(Runnable r) {
                Thread t = new Thread(r, "Custom-Worker-" + threadId.incrementAndGet());
                t.setDaemon(false); // 非守护线程
                t.setPriority(Thread.NORM_PRIORITY);
                System.out.println("  [ThreadFactory] 创建新线程: " + t.getName());
                return t;
            }
        };

        // 创建线程池示例
        ThreadPoolExecutor executor = new ThreadPoolExecutor(
            2,                                          // 1. corePoolSize: 核心线程数=2
            5,                                          // 2. maximumPoolSize: 最大线程数=5
            60,                                         // 3. keepAliveTime: 空闲存活60秒
            TimeUnit.SECONDS,                           // 4. unit: 时间单位=秒
            new LinkedBlockingQueue<>(3),               // 5. workQueue: 队列容量=3
            customFactory,                              // 6. threadFactory: 自定义线程工厂
            new ThreadPoolExecutor.AbortPolicy()        // 7. handler: 拒绝策略=AbortPolicy
        );

        System.out.println("\n创建的线程池参数:");
        System.out.println("  核心线程数: " + executor.getCorePoolSize());
        System.out.println("  最大线程数: " + executor.getMaximumPoolSize());
        System.out.println("  空闲存活时间: " + executor.getKeepAliveTime(TimeUnit.SECONDS) + "秒");
        System.out.println("  队列容量: " + executor.getQueue().remainingCapacity());

        // 关闭线程池
        executor.shutdown();
        System.out.println();
    }

    // ==================== 第二部分：线程池工作流程 ====================

    /**
     * 2. 线程池工作流程演示
     */
    public static void demonstrateWorkflow() throws InterruptedException {
        System.out.println("========================================");
        System.out.println("第二部分：线程池工作流程");
        System.out.println("========================================");

        /*
         * 线程池执行任务的流程（execute方法）：
         * 
         * 1. 如果当前运行的线程数 < corePoolSize：
         *    - 创建新线程（核心线程）来执行任务
         *    - 即使有其他核心线程空闲也会创建
         * 
         * 2. 如果当前运行的线程数 >= corePoolSize：
         *    - 尝试将任务放入workQueue排队
         * 
         * 3. 如果队列已满：
         *    - 如果当前线程数 < maximumPoolSize：
         *      * 创建新线程（非核心线程）来执行任务
         *    - 否则（当前线程数 >= maximumPoolSize）：
         *      * 执行拒绝策略
         * 
         * 核心线程 vs 非核心线程：
         * - 核心线程：默认不会超时回收，会一直等待新任务
         * - 非核心线程：超过keepAliveTime没有任务就会被回收
         */

        // 创建线程池：核心2，最大4，队列容量2
        ThreadPoolExecutor executor = new ThreadPoolExecutor(
            2, 4, 30, TimeUnit.SECONDS,
            new LinkedBlockingQueue<>(2),
            new ThreadPoolExecutor.CallerRunsPolicy()
        );

        System.out.println("线程池参数: 核心线程=2, 最大线程=4, 队列容量=2\n");

        // 提交8个任务，每个任务执行1秒
        for (int i = 1; i <= 8; i++) {
            final int taskId = i;
            System.out.println("提交任务 " + taskId + " | 活跃线程: " + executor.getActiveCount() 
                + " | 队列大小: " + executor.getQueue().size() + " | 池大小: " + executor.getPoolSize());

            executor.execute(() -> {
                System.out.println("  -> 任务 " + taskId + " 开始执行，线程: " + Thread.currentThread().getName());
                try {
                    Thread.sleep(1000); // 模拟任务执行
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
                System.out.println("  <- 任务 " + taskId + " 执行完成");
            });

            Thread.sleep(100); // 稍微延迟以便观察
        }

        // 等待所有任务完成
        Thread.sleep(5000);
        System.out.println("\n最终状态 - 活跃线程: " + executor.getActiveCount() 
            + " | 队列大小: " + executor.getQueue().size() + " | 池大小: " + executor.getPoolSize());

        executor.shutdown();
        System.out.println();
    }

    // ==================== 第三部分：四种拒绝策略 ====================

    /**
     * 3. 四种拒绝策略演示
     */
    public static void demonstrateRejectionPolicies() throws InterruptedException {
        System.out.println("========================================");
        System.out.println("第三部分：四种拒绝策略");
        System.out.println("========================================");

        /*
         * JDK提供的四种拒绝策略：
         * 
         * 1. AbortPolicy（默认）：
         *    - 直接抛出RejectedExecutionException异常
         *    - 适用于：需要严格保证任务不丢失的场景
         *    - 风险：如果不处理异常，任务会丢失
         * 
         * 2. CallerRunsPolicy：
         *    - 由提交任务的调用者线程来执行任务
         *    - 适用于：需要保证任务一定被执行，且能接受性能下降的场景
         *    - 优点：提供自然的背压机制，当线程池忙时，调用者线程会被阻塞
         * 
         * 3. DiscardPolicy：
         *    - 静默丢弃被拒绝的任务，不抛异常
         *    - 适用于：允许任务丢失的场景（如日志收集）
         *    - 风险：任务会无声无息地丢失
         * 
         * 4. DiscardOldestPolicy：
         *    - 丢弃队列中最老的任务（队头），然后重新尝试提交
         *    - 适用于：只关心最新数据的场景（如实时行情）
         *    - 风险：可能会丢失重要任务
         */

        // 3.1 AbortPolicy演示
        System.out.println("--- 3.1 AbortPolicy（默认）---");
        demonstrateAbortPolicy();

        // 3.2 CallerRunsPolicy演示
        System.out.println("\n--- 3.2 CallerRunsPolicy ---");
        demonstrateCallerRunsPolicy();

        // 3.3 DiscardPolicy演示
        System.out.println("\n--- 3.3 DiscardPolicy ---");
        demonstrateDiscardPolicy();

        // 3.4 DiscardOldestPolicy演示
        System.out.println("\n--- 3.4 DiscardOldestPolicy ---");
        demonstrateDiscardOldestPolicy();
    }

    private static void demonstrateAbortPolicy() throws InterruptedException {
        // 创建一个很小的线程池来触发拒绝
        ThreadPoolExecutor executor = new ThreadPoolExecutor(
            1, 1, 0, TimeUnit.SECONDS,
            new ArrayBlockingQueue<>(1),
            new ThreadPoolExecutor.AbortPolicy()
        );

        // 提交3个任务，但只能容纳2个（1个执行 + 1个排队）
        for (int i = 1; i <= 3; i++) {
            final int taskId = i;
            try {
                executor.execute(() -> {
                    System.out.println("  任务 " + taskId + " 执行");
                    try { Thread.sleep(1000); } catch (InterruptedException e) {}
                });
                System.out.println("  任务 " + taskId + " 提交成功");
            } catch (RejectedExecutionException e) {
                System.out.println("  任务 " + taskId + " 被拒绝: " + e.getMessage());
            }
        }

        executor.shutdown();
    }

    private static void demonstrateCallerRunsPolicy() throws InterruptedException {
        ThreadPoolExecutor executor = new ThreadPoolExecutor(
            1, 1, 0, TimeUnit.SECONDS,
            new ArrayBlockingQueue<>(1),
            new ThreadPoolExecutor.CallerRunsPolicy()
        );

        System.out.println("  提交任务的线程: " + Thread.currentThread().getName());

        for (int i = 1; i <= 3; i++) {
            final int taskId = i;
            executor.execute(() -> {
                System.out.println("  任务 " + taskId + " 由线程 " + Thread.currentThread().getName() + " 执行");
                try { Thread.sleep(500); } catch (InterruptedException e) {}
            });
            System.out.println("  任务 " + taskId + " 提交完成");
        }

        executor.shutdown();
        executor.awaitTermination(3, TimeUnit.SECONDS);
    }

    private static void demonstrateDiscardPolicy() throws InterruptedException {
        ThreadPoolExecutor executor = new ThreadPoolExecutor(
            1, 1, 0, TimeUnit.SECONDS,
            new ArrayBlockingQueue<>(1),
            new ThreadPoolExecutor.DiscardPolicy()
        );

        int submitted = 0;
        for (int i = 1; i <= 3; i++) {
            final int taskId = i;
            executor.execute(() -> {
                System.out.println("  任务 " + taskId + " 执行");
                try { Thread.sleep(1000); } catch (InterruptedException e) {}
            });
            submitted++;
            System.out.println("  任务 " + taskId + " 已提交（可能被丢弃）");
        }

        System.out.println("  总共提交了 " + submitted + " 个任务，但只有部分会被执行");
        executor.shutdown();
    }

    private static void demonstrateDiscardOldestPolicy() throws InterruptedException {
        ThreadPoolExecutor executor = new ThreadPoolExecutor(
            1, 1, 0, TimeUnit.SECONDS,
            new ArrayBlockingQueue<>(1),
            new ThreadPoolExecutor.DiscardOldestPolicy()
        );

        // 提交多个任务，观察哪个会被丢弃
        for (int i = 1; i <= 4; i++) {
            final int taskId = i;
            executor.execute(() -> {
                System.out.println("  任务 " + taskId + " 执行");
                try { Thread.sleep(500); } catch (InterruptedException e) {}
            });
            System.out.println("  任务 " + taskId + " 提交");
            Thread.sleep(100);
        }

        executor.shutdown();
        executor.awaitTermination(3, TimeUnit.SECONDS);
        System.out.println("  注意：任务1可能会被丢弃，因为它是队列中最老的任务");
    }
}"}

